function tab(name){if(name==='appointments'&&current){fillFilters();run(renderAgenda)}if(name==='reports'&&current)renderReports();if(name==='settings'&&current)run(loadReward);tabs.forEach(t=>$(t).hidden=t!==name);document.querySelectorAll('[data-tab]').forEach(b=>(b.classList.toggle('secondary',b.dataset.tab!==name),b.setAttribute('aria-current',String(b.dataset.tab===name))));}
