function option(value,label){const o=document.createElement('option');o.value=value;o.textContent=label;return o;}
async function load(preferred){const uid=user.uid;const snap=await getDocs(query(collection(db,'establishments'),where('ownerUid','==',uid)));if(user?.uid!==uid)return;units=snap.docs.map(d=>({id:d.id,...d.data()}));$('orgs').replaceChildren(...units.map(u=>option(u.id,u.name)));$('unitbar').hidden=!units.length;$('editOrg').parentElement.hidden=!units.length;$('editOrg').hidden=!units.length;$('create').parentElement.open=!units.length;$('createTitle').textContent=units.length?'Nova unidade':'Cadastre seu primeiro estabelecimento';if(!units.length){current=null;tab('settings');return;}await selectUnit(units.find(u=>u.id===(preferred||localStorage.getItem('unit:'+uid)))||units[0]);}
async function selectUnit(unit){stopManager?.();const g=++generation;current=unit;financeRows=[];$('totalCustomers').textContent='…';$('managerMetrics').replaceChildren();renderReports();localStorage.setItem('unit:'+user.uid,unit.id);$('orgs').value=unit.id;$('orgTitle').textContent=unit.name;$('editName').value=unit.name;$('editSegment').value=unit.segment;for(const [id,k] of brandFields)$(id).value=unit.brand?.[k]||'';pros=[];services=[];categories=[];$('categoryReset').click();resetPro();resetService();render();tab('dashboard');await refresh(g,unit.id);await publishControls();watchManager(unit.id);}
async function refresh(g=generation,id=current.id){const [p,s,c]=await Promise.all(['professionals','services','categories'].map(k=>getDocs(collection(db,'establishments',id,k))));if(g!==generation||current?.id!==id)return;pros=p.docs.map(d=>({id:d.id,...d.data()}));services=s.docs.map(d=>({id:d.id,...d.data()}));categories=c.docs.map(d=>({id:d.id,...d.data()}));render();await syncCatalog(id);}
