$('create').onsubmit=e=>{e.preventDefault();run(async()=>{const uid=user.uid,r=doc(collection(db,'establishments')),batch=writeBatch(db);batch.set(r,{name:$('orgName').value.trim(),segment:$('segment').value,ownerUid:uid,createdAt:serverTimestamp()});batch.set(doc(r,'members',uid),{role:'owner',uid});await batch.commit();$('create').reset();await load(r.id);$('status').textContent='Unidade cadastrada!';})};
