function serviceChoices(selected){$('proServices').replaceChildren();services.filter(s=>s.active||selected.includes(s.id)).forEach(s=>{const l=document.createElement('label'),c=document.createElement('input');l.className='check';c.type='checkbox';c.value=s.id;c.checked=selected.includes(s.id);l.append(c,document.createTextNode(s.name+(s.active?'':' (inativo)')));$('proServices').append(l);});}
function card(parent,title,detail,active,edit,toggle,photo){const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p'),row=document.createElement('div');h.textContent=title;p.textContent=detail+' · '+(active?'Ativo':'Inativo');row.className='actions';if(photo&&(/^(https:\/\/|data:image\/jpeg;base64,)/).test(photo)){const img=document.createElement('img');img.src=photo;img.alt='';img.className='avatar';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();a.append(img);}else if(parent===$('proList')){const v=document.createElement('span');v.className='avatar initials';v.textContent=initials(title);a.append(v);}a.append(h,p);for(const [label,fn] of [['Editar',edit],[active?'Desativar':'Ativar',toggle]]){const b=document.createElement('button');b.className='secondary';b.textContent=label;b.onclick=fn;row.append(b);}a.append(row);parent.append(a);}
function render(){renderCategories();renderScheduleChoices();const selected=[...$('proServices').querySelectorAll('input:checked')].map(c=>c.value);serviceChoices(selected);$('proCount').textContent=pros.filter(p=>p.active).length;$('serviceCount').textContent=services.filter(s=>s.active).length;$('proList').replaceChildren();$('serviceList').replaceChildren();for(const c of categories)categoryRoot(c.id);for(const p of pros)card($('proList'),p.name,p.specialty+' · '+p.email,p.active,()=>{$('proId').value=p.id;$('proName').value=p.name;$('specialty').value=p.specialty;$('proEmail').value=p.email;showPhoto(p.photo||'');$('proUid').value=p.uid||'';$('proPassword').value='';$('proEmail').readOnly=!!p.uid;$('proActive').checked=p.active;serviceChoices(p.serviceIds||[]);$('proForm').parentElement.open=true;$('proForm').scrollIntoView();},()=>run(async()=>{await updateDoc(ref('professionals',p.id),{active:!p.active});await refresh();}),p.photo);for(const s of services)card(categoryRoot(s.categoryId),s.name,(s.priceCents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+' · '+s.duration+' min',s.active,()=>{$('serviceId').value=s.id;$('serviceCategory').value=s.categoryId||'';$('serviceName').value=s.name;$('price').value=s.priceCents/100;$('duration').value=s.duration;$('serviceActive').checked=s.active;$('serviceForm').parentElement.open=true;$('serviceForm').scrollIntoView();},()=>run(async()=>{await updateDoc(ref('services',s.id),{active:!s.active});await refresh();}));}
async function save(kind,id,data){const g=generation,unit=current.id,r=id?ref(kind,id):doc(collection(db,'establishments',unit,kind));if(kind==='professionals'){const old=pros.find(p=>p.id===id);const batch=writeBatch(db);if(id)batch.update(r,data);else batch.set(r,{...data,createdAt:serverTimestamp()});if(old?.uid&&old.uid!==data.uid)batch.delete(doc(db,'staffAccess',old.uid,'profiles',unit+'_'+r.id));if(data.uid)batch.set(doc(db,'staffAccess',data.uid,'profiles',unit+'_'+r.id),{org:unit,professional:r.id});await batch.commit();}else if(id)await updateDoc(r,data);else await setDoc(r,{...data,createdAt:serverTimestamp()});if(g!==generation)return;kind==='services'?resetService():resetPro();await refresh(g,unit);$('status').textContent='Cadastro salvo!';}
$('proForm').onsubmit=e=>{e.preventDefault();run(async()=>{const id=$('proId').value,org=current.id,g=generation,email=$('proEmail').value.trim(),password=$('proPassword').value;let uid=$('proUid').value.trim();if(uid&&password)throw Error('Conta existente: use a recuperação de senha.');if(!uid&&password){const secondary=initializeApp(app.options,'staff-'+crypto.randomUUID());const secondaryAuth=getAuth(secondary);try{const c=await createUserWithEmailAndPassword(secondaryAuth,email,password);uid=c.user.uid;$('proUid').value=uid;$('proPassword').value='';}finally{await signOut(secondaryAuth).catch(()=>{});await deleteApp(secondary);}}if(g!==generation||current?.id!==org)throw Error('Unidade alterada durante cadastro.');await save('professionals',id,{name:$('proName').value.trim(),specialty:$('specialty').value.trim(),email,photo:$('photo').value.trim(),uid,active:$('proActive').checked,serviceIds:[...$('proServices').querySelectorAll('input:checked')].map(c=>c.value)});});};
$('serviceForm').onsubmit=e=>{e.preventDefault();run(()=>save('services',$('serviceId').value,{name:$('serviceName').value.trim(),categoryId:$('serviceCategory').value,priceCents:Math.round(Number($('price').value)*100),duration:Number($('duration').value),active:$('serviceActive').checked}));};
function initials(n){return n.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'+';}
function showPhoto(v){$('photo').value=v;$('pickPhoto').replaceChildren();if(v){const im=new Image();im.src=v;im.alt='Foto do profissional';$('pickPhoto').append(im);}else $('pickPhoto').textContent=initials($('proName').value);}
$('pickPhoto').onclick=()=>$('photoFile').click();$('removePhoto').onclick=()=>{ $('photoFile').value='';showPhoto('');};$('proName').oninput=()=>{if(!$('photo').value)showPhoto('');};
let cropImage=null,cropGeneration=0,cropId='';
function drawCrop(){if(!cropImage)return;const c=$('cropCanvas'),ctx=c.getContext('2d'),z=Number($('cropZoom').value),scale=256/Math.min(cropImage.width,cropImage.height)*z,w=cropImage.width*scale,h=cropImage.height*scale;ctx.fillStyle='#fff';ctx.fillRect(0,0,256,256);ctx.drawImage(cropImage,(256-w)/2+Number($('cropX').value)*(w-256)/2,(256-h)/2+Number($('cropY').value)*(h-256)/2,w,h);}
$('photoFile').onchange=()=>run(async()=>{const f=$('photoFile').files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15000000)throw Error('Escolha JPG, PNG ou WebP de até 15 MB.');cropGeneration=generation;cropId=$('proId').value;cropImage?.close();cropImage=await createImageBitmap(f);$('cropZoom').value=1;$('cropX').value=$('cropY').value=0;drawCrop();$('cropDialog').showModal();});
for(const id of ['cropZoom','cropX','cropY'])$(id).oninput=drawCrop;
$('cropSave').onclick=()=>{if(cropGeneration===generation&&cropId===$('proId').value)showPhoto($('cropCanvas').toDataURL('image/jpeg',.75));$('cropDialog').close();};$('cropCancel').onclick=()=>$('cropDialog').close();$('cropDialog').onclose=()=>{cropImage?.close();cropImage=null;$('photoFile').value='';};
let drag=null;$('cropCanvas').onpointerdown=e=>{drag=[e.clientX,e.clientY,Number($('cropX').value),Number($('cropY').value)];e.target.setPointerCapture(e.pointerId);};$('cropCanvas').onpointermove=e=>{if(!drag)return;$('cropX').value=Math.max(-1,Math.min(1,drag[2]+(e.clientX-drag[0])/100));$('cropY').value=Math.max(-1,Math.min(1,drag[3]+(e.clientY-drag[1])/100));drawCrop();};$('cropCanvas').onpointerup=$('cropCanvas').onpointercancel=()=>drag=null;
const weekdays=['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];
function buildWeek(parent,data={}){parent.replaceChildren();weekdays.forEach((name,i)=>{const d=data.week?.[i]||{active:i<5,start:'09:00',end:'18:00',breakStart:'12:00',breakEnd:'13:00'};const row=document.createElement('fieldset');row.innerHTML=`<legend>${name}</legend><label class="check"><input type="checkbox" data-k="active"> Trabalha</label><div class="grid">${[['start','Início'],['end','Fim'],['breakStart','Intervalo início'],['breakEnd','Intervalo fim']].map(([k,l])=>`<label>${l}<input type="time" data-k="${k}"></label>`).join('')}</div>`;row.querySelector('[data-k=active]').checked=d.active;for(const k of ['start','end','breakStart','breakEnd'])row.querySelector(`[data-k=${k}]`).value=d[k]||'';parent.append(row);});}
function readWeek(parent,off){const week=[...parent.children].map(row=>{const d={};for(const el of row.querySelectorAll('input'))d[el.dataset.k]=el.type==='checkbox'?el.checked:el.value;if(d.active&&(!d.start||!d.end||d.start>=d.end||((d.breakStart||d.breakEnd)&&(!d.breakStart||!d.breakEnd||d.breakStart<d.start||d.breakEnd>d.end||d.breakStart>=d.breakEnd))))throw Error('Revise os horários e intervalos.');return d;});const daysOff=off.split(',').map(x=>x.trim()).filter(Boolean);if(daysOff.length>366||daysOff.some(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x)||isNaN(Date.parse(x))||new Date(x).toISOString().slice(0,10)!==x))throw Error('Revise as datas de folga.');return {week,daysOff};}
let scheduleToken=0;function renderScheduleChoices(){const old=$('schedulePro').value;$('schedulePro').replaceChildren(...pros.map(p=>option(p.id,p.name)));if(pros.some(p=>p.id===old))$('schedulePro').value=old;run(loadSchedule);}
async function loadSchedule(){const t=++scheduleToken,id=$('schedulePro').value;$('scheduleForm').hidden=!id;if(!id)return;const snap=await getDoc(ref('availability',id));if(t!==scheduleToken)return;const d=snap.data()||{};buildWeek($('week'),d);$('daysOff').value=(d.daysOff||[]).join(', ');calendar($('daysOff'));}
demoButton($('scheduleForm'),$('week'),$('daysOff'));$('schedulePro').onchange=()=>run(loadSchedule);$('scheduleForm').onsubmit=e=>{e.preventDefault();run(async()=>{await setDoc(ref('availability',$('schedulePro').value),readWeek($('week'),$('daysOff').value));$('status').textContent='Escala salva!';});};
let staff=[];async function loadStaff(){const uid=user.uid;const snap=await getDocs(collection(db,'staffAccess',uid,'profiles'));if(user?.uid!==uid)return;staff=snap.docs.map(x=>x.data());$('staffPanel').hidden=!staff.length;if(!staff.length)return;if(!units.length)$('panel').hidden=true;$('staffProfiles').replaceChildren(...staff.map((p,i)=>option(String(i),p.org+' / '+p.professional)));await staffSchedule();}
async function staffSchedule(){const p=staff[Number($('staffProfiles').value)];if(!p)return;const r=doc(db,'establishments',p.org,'availability',p.professional);const snap=await getDoc(r);const profile=await getDoc(doc(db,'establishments',p.org,'professionals',p.professional));const d=snap.data()||{};const root=$('staffSchedule');root.replaceChildren();const h=document.createElement('h3');h.textContent=profile.data()?.name||'Profissional';const form=document.createElement('form'),week=document.createElement('div'),off=document.createElement('input'),label=document.createElement('label'),button=document.createElement('button');label.textContent='Folgas (AAAA-MM-DD, separadas por vírgula)';off.value=(d.daysOff||[]).join(', ');label.append(off);button.textContent='Salvar minha escala';buildWeek(week,d);form.append(week,label,button);root.append(h,form);calendar(off);demoButton(form,week,off);watchStaff(p);form.onsubmit=e=>{e.preventDefault();run(async()=>{await setDoc(r,readWeek(week,off.value));$('status').textContent='Escala salva!';});};}
