function collapse(id,title){const f=$(id),d=document.createElement('details'),s=document.createElement('summary');s.textContent=title;f.before(d);d.append(s,f);return d;}
collapse('proForm','Cadastrar profissional');collapse('serviceForm','Cadastrar serviço');collapse('categoryForm','Cadastrar categoria');collapse('editOrg','Dados da unidade');collapse('create','Cadastrar nova unidade');
function calendar(input){input.parentElement.querySelector('.calendar')?.remove();const root=document.createElement('div');root.className='calendar';input.after(root);let month=new Date();month.setDate(1);function renderCal(){root.replaceChildren();const bar=document.createElement('div');bar.className='row';const prev=document.createElement('button'),next=document.createElement('button'),title=document.createElement('b');prev.type=next.type='button';prev.textContent='‹';next.textContent='›';title.textContent=month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});prev.onclick=()=>{month.setMonth(month.getMonth()-1);renderCal()};next.onclick=()=>{month.setMonth(month.getMonth()+1);renderCal()};bar.append(prev,title,next);root.append(bar);const grid=document.createElement('div');grid.className='calgrid';for(const d of ['D','S','T','Q','Q','S','S']){const x=document.createElement('small');x.textContent=d;grid.append(x)}for(let i=0;i<month.getDay();i++)grid.append(document.createElement('span'));const off=new Set(input.value.split(',').map(x=>x.trim()).filter(Boolean));for(let i=1;i<=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();i++){const key=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(i).padStart(2,'0')}`,b=document.createElement('button');b.type='button';b.textContent=i;b.className=off.has(key)?'':'secondary';b.onclick=()=>{off.has(key)?off.delete(key):off.add(key);input.value=[...off].sort().join(', ');renderCal()};grid.append(b)}root.append(grid)}renderCal();}
const bookingOrg=new URLSearchParams(location.search).get('agenda');let catalog=null,availability=null,stopSlots=null,stopAv=null,stopHistory=null,stopStaff=null,slotRows=[];
async function syncCatalog(id){if(current?.id!==id)return;const reward=(await getDoc(doc(db,'establishments',id,'loyaltySettings','campaign'))).data()||null;if(current?.id!==id)return;await setDoc(doc(db,'publicCatalogs',id),{name:current.name,brand:current.brand||{},reward,professionals:pros.filter(p=>p.active).map(({id,name,specialty,photo,serviceIds})=>({id,name,specialty,photo:photo||'',serviceIds:serviceIds||[]})),services:services.filter(s=>s.active).map(({id,name,duration,priceCents,categoryId})=>({id,name,duration,priceCents,category:categories.find(c=>c.id===categoryId)?.name||'Sem categoria'}))});}
async function publishControls(){const root=$('publicLink');root.replaceChildren();const b=document.createElement('button');b.textContent='Publicar / atualizar agenda pública';b.onclick=()=>run(async()=>{await syncCatalog(current.id);$('status').textContent='Agenda pública atualizada.'});const link=document.createElement('a');link.href='?agenda='+encodeURIComponent(current.id);link.textContent='Abrir central do cliente';root.append(b,link);const requests=$('requests');requests.replaceChildren();const snap=await getDocs(collection(db,'establishments',current.id,'bookingRequests'));for(const d of snap.docs){const x=d.data(),el=document.createElement('article');el.textContent=`${x.date} ${x.time} · ${x.name} · ${x.phone} · ${statusNames[x.status]||'Status desconhecido'}`;requests.append(el)}}
async function loadBooking(u){$('customerPanel').hidden=false;$('login').hidden=!!u;$('customerLogout').hidden=!u;$('customerName').value=u?.displayName||'';const s=await getDoc(doc(db,'publicCatalogs',bookingOrg));if(!s.exists())throw Error('Agenda ainda não publicada.');catalog=s.data();$('customerTitle').textContent=catalog.name;renderBrand(catalog.brand);$('bookingPro').replaceChildren(...catalog.professionals.map(p=>option(p.id,p.name)));$('bookingDate').min=dateKey(new Date());if(!$('bookingDate').value)$('bookingDate').value=dateKey(new Date());watchCustomer(u);await bookingChoices();}
let calMonth=new Date(), locksReady=false, availabilityReady=false;
function renderBookingCalendar(){const root=$('bookingCalendar');root.replaceChildren();const header=document.createElement('div');header.className='cal-head';const title=document.createElement('strong');title.textContent=calMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});for(const n of [-1,1]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=n<0?'‹':'›';b.onclick=()=>{calMonth=new Date(calMonth.getFullYear(),calMonth.getMonth()+n,1);renderBookingCalendar()};if(n<0)header.append(b,title);else header.append(b)}root.append(header);const grid=document.createElement('div');grid.className='cal-grid';for(const d of ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']){const el=document.createElement('small');el.textContent=d;grid.append(el)}const y=calMonth.getFullYear(),m=calMonth.getMonth();for(let i=0;i<new Date(y,m,1).getDay();i++)grid.append(document.createElement('span'));for(let i=1;i<=new Date(y,m+1,0).getDate();i++){const d=new Date(y,m,i),key=dateKey(d),b=document.createElement('button');b.type='button';b.textContent=i;b.disabled=key<dateKey(new Date())||!availabilityReady||!availability?.week?.[(d.getDay()+6)%7]?.active||availability.daysOff?.includes(key);b.className=key===$('bookingDate').value?'chosen':'secondary';b.onclick=()=>{$('bookingDate').value=key;watchSlots();renderBookingCalendar()};grid.append(b)}root.append(grid);}
async function bookingChoices(){const p=catalog?.professionals.find(p=>p.id===$('bookingPro').value);stopAv?.();stopSlots?.();availability=null;availabilityReady=false;locksReady=false;$('bookingAvatar').replaceChildren();$('bookingService').replaceChildren();$('bookingDate').value='';if(!p){times();return;}if(p.photo){const im=new Image();im.className='avatar';im.src=p.photo;$('bookingAvatar').append(im)}const groups=new Map();for(const s of (catalog.services||[]).filter(s=>(p.serviceIds||[]).includes(s.id))){const k=s.category||'Sem categoria';if(!groups.has(k)){const g=document.createElement('optgroup');g.label=k;groups.set(k,g);$('bookingService').append(g)}groups.get(k).append(option(s.id,s.name+' · '+s.duration+' min · '+(s.priceCents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})));}$('serviceHint').textContent=groups.size?'':'Nenhum serviço vinculado a este profissional. Peça ao gerente para vincular serviços ativos.';times();stopAv=onSnapshot(doc(db,'establishments',bookingOrg,'availability',p.id),snap=>{availability=snap.data();availabilityReady=true;renderBookingCalendar();times();},e=>{$('serviceHint').textContent=e.message;});}
function times(){const date=$('bookingDate').value,s=catalog?.services.find(s=>s.id===$('bookingService').value),d=availability?.week?.[(new Date(date+'T12:00:00').getDay()+6)%7],old=$('bookingTime').value; $('bookingTime').replaceChildren(option('','Selecione'));const root=$('timeButtons');root.replaceChildren();$('bookingSummary').textContent='';$('bookingForm').querySelector('button[type=submit]').disabled=true;if(!s||!date||!d?.active||availability.daysOff?.includes(date)||!locksReady){root.textContent=!date?'Selecione um dia no calendário.':!locksReady?'Consultando horários…':'Sem disponibilidade.';return;}const mins=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};for(let i=mins(d.start);i+s.duration<=mins(d.end);i+=15){if(d.breakStart&&i<mins(d.breakEnd)&&i+s.duration>mins(d.breakStart))continue;const t=String(Math.floor(i/60)).padStart(2,'0')+':'+String(i%60).padStart(2,'0');if(new Date(date+'T'+t)<=new Date())continue;if(slotRows.some(z=>i<z.end&&i+s.duration>z.start)){const b=document.createElement('button');b.type='button';b.className='occupied';b.textContent=t+' · ocupado';b.onclick=()=>{const next=[...$('bookingTime').options].map(o=>o.value).find(v=>v>t);$('bookingNotice').textContent='Já existe um agendamento neste período. '+(next?'Próximo horário disponível: '+next+'.':'Não há horário posterior livre neste dia.');};root.append(b);continue;}$('bookingTime').append(option(t,t));const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=t;b.onclick=()=>{$('bookingTime').value=t;selectTime();};root.append(b);}if($('bookingTime').options.length===1&&root.childElementCount===0)root.textContent='Nenhum horário livre neste dia.';if([...$('bookingTime').options].some(o=>o.value===old))$('bookingTime').value=old;else if(old){const next=[...$('bookingTime').options].map(o=>o.value).find(v=>v>old);$('bookingNotice').textContent='O horário selecionado não está mais disponível. '+(next?'Próximo horário: '+next:'Escolha outro dia ou horário.');}selectTime();}
function selectTime(){const t=$('bookingTime').value,s=catalog?.services.find(s=>s.id===$('bookingService').value);for(const b of $('timeButtons').querySelectorAll('button'))b.classList.toggle('chosen',b.textContent===t);$('bookingSummary').textContent=t&&s?s.name+' · '+$('bookingDate').value.split('-').reverse().join('/')+' às '+t:'';$('bookingForm').querySelector('button[type=submit]').disabled=!t;}
$('bookingPro').onchange=()=>run(bookingChoices);$('bookingService').onchange=()=>{$('bookingTime').value='';times()};$('bookingDate').onchange=watchSlots;$('customerLogout').onclick=()=>signOut(auth);$('bookingForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(!auth.currentUser)throw Error('Entre ou crie sua conta acima antes de solicitar.');if(!$('bookingTime').value||!locksReady)throw Error('Escolha um horário disponível.');const selectedTime=$('bookingTime').value, selectedDate=$('bookingDate').value, selectedPro=$('bookingPro').value, selectedService=$('bookingService').value;const duration=catalog.services.find(s=>s.id===selectedService)?.duration;const [hh,mm]=selectedTime.split(':').map(Number),start=hh*60+mm;const latest=await getDoc(doc(db,'establishments',bookingOrg,'bookingLocks',selectedPro+'_'+selectedDate));if(!duration||(latest.data()?.slots||[]).some(z=>start<z.end&&start+duration>z.start)){times();throw Error('Horário já ocupado. Escolha outro horário.');}if(selectedTime!==$('bookingTime').value||selectedDate!==$('bookingDate').value||selectedPro!==$('bookingPro').value||selectedService!==$('bookingService').value)throw Error('Seleção alterada. Confira o horário.');await setDoc(doc(collection(db,'establishments',bookingOrg,'bookingRequests')),{uid:auth.currentUser.uid,email:auth.currentUser.email,name:$('customerName').value.trim(),phone:$('customerPhone').value,professional:$('bookingPro').value,service:$('bookingService').value,date:$('bookingDate').value,time:$('bookingTime').value,priceCents:catalog.services.find(s=>s.id===selectedService).priceCents,status:'pending',createdAt:serverTimestamp()});$('status').textContent='Seu agendamento foi efetuado com sucesso! Consulte no bloco Meus agendamentos. Aguarde a confirmação.';$('bookingTime').value='';times();});};

