async function renderAgenda(){if(!current)return;const org=current.id,g=generation,snap=await getDocs(collection(db,'establishments',org,'bookingRequests'));if(g!==generation)return;const root=$('agendaList');root.replaceChildren();const start=new Date($('agendaDate').value+'T12:00:00'),end=new Date(start),mode=$('agendaView').value;if(mode==='week'){start.setDate(start.getDate()-(start.getDay()+6)%7);end.setTime(start.getTime());end.setDate(end.getDate()+6)}if(mode==='month'){start.setDate(1);end.setMonth(end.getMonth()+1,0)}const rows=snap.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.date>=dateKey(start)&&x.date<=dateKey(end)&&(!$('filterPro').value||x.professional===$('filterPro').value)&&(!$('filterStatus').value||x.status===$('filterStatus').value)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const day=dateKey(d),section=document.createElement('details'),h=document.createElement('summary');const list=rows.filter(x=>x.date===day);h.textContent=d.toLocaleDateString('pt-BR',{weekday:'short',day:'numeric',month:'long'})+' · '+list.length+' atendimento(s)';section.open=mode==='day'||list.length>0;section.append(h);for(const x of list){const a=document.createElement('article');a.textContent=`${x.time} · ${x.name} · ${pros.find(p=>p.id===x.professional)?.name||'Profissional'} · ${services.find(s=>s.id===x.service)?.name||'Serviço'} · ${statusNames[x.status]||'Status desconhecido'}`;for(const [label,status] of (x.status==='pending'?[['Confirmar','confirmed'],['Recusar','cancelled']]:x.status==='confirmed'?[['Concluir','completed'],['Cancelar','cancelled'],['Não compareceu','no_show']]:[])){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(async()=>{await changeBooking(org,x.id,status);await renderAgenda();await publishControls();});a.append(b)}section.append(a)}root.append(section)}}
async function changeBooking(org,id,status){const r=doc(db,'establishments',org,'bookingRequests',id);await runTransaction(db,async tx=>{const snap=await tx.get(r),x=snap.data();if(!x)throw Error('Solicitação inexistente.');if(!(x.status==='pending'&&['confirmed','cancelled'].includes(status)||x.status==='confirmed'&&['completed','cancelled','no_show'].includes(status)))throw Error('Status já alterado.');if(status==='confirmed'){const service=current?.id===org?(await tx.get(doc(db,'establishments',org,'services',x.service))).data():{...(await tx.get(doc(db,'publicCatalogs',org))).data()?.services?.find(s=>s.id===x.service),active:true},pro=(await tx.get(doc(db,'establishments',org,'professionals',x.professional))).data(),av=(await tx.get(doc(db,'establishments',org,'availability',x.professional))).data();const mins=t=>{const [h,m]=t.split(':').map(Number);return h*60+m};const day=av?.week?.[(new Date(x.date+'T12:00:00').getDay()+6)%7],start=mins(x.time),end=start+(service?.duration||0);if(!service?.active||!Number.isFinite(service.duration)||!pro?.active||!pro.serviceIds.includes(x.service)||!day?.active||av.daysOff?.includes(x.date)||start<mins(day.start)||end>mins(day.end)||day.breakStart&&start<mins(day.breakEnd)&&end>mins(day.breakStart)||!Number.isFinite(start)||new Date(x.date+'T'+x.time)<=new Date())throw Error('Horário indisponível.');const lock=doc(db,'establishments',org,'bookingLocks',x.professional+'_'+x.date),ls=await tx.get(lock),slots=ls.data()?.slots||[];if(slots.some(z=>start<z.end&&end>z.start))throw Error('Horário já reservado.');tx.set(lock,{professional:x.professional,date:x.date,slots:[...slots,{id,start,end}]});}else if(status==='cancelled'&&x.status==='confirmed'){const lock=doc(db,'establishments',org,'bookingLocks',x.professional+'_'+x.date),ls=await tx.get(lock);tx.set(lock,{professional:x.professional,date:x.date,slots:(ls.data()?.slots||[]).filter(z=>z.id!==id)});}tx.update(r,{status});});if(status==='confirmed')await prepareConfirmation(org,id).catch(e=>{$('status').textContent='Confirmado, mas não foi possível preparar WhatsApp: '+e.message;});}
