async function renderCustomers(){if(!current)return;const g=generation,org=current.id;const [snap,book,red]=await Promise.all([getDocs(collection(db,'establishments',org,'customers')),getDocs(collection(db,'establishments',org,'bookingRequests')),getDocs(collection(db,'establishments',org,'rewardBalances'))]);if(g!==generation)return;const rows=book.docs.map(d=>d.data()),balances=new Map(red.docs.map(d=>[d.id,d.data()])),people=new Map();for(const d of snap.docs){const x=d.data();people.set(x.email.toLowerCase(),{...x,id:d.id});}for(const x of rows){const key=x.email.toLowerCase(),p=people.get(key)||{name:x.name,email:x.email,phone:x.phone};p.uid=x.uid;people.set(key,p);}const campaign=(await getDoc(doc(db,'establishments',org,'loyaltySettings','campaign'))).data();if(g!==generation)return;const root=$('customerList');root.replaceChildren();const search=$('crmSearch').value.toLowerCase();$('crmSummary').textContent=people.size+' clientes · '+rows.filter(x=>x.status==='completed').length+' atendimentos concluídos';for(const x of [...people.values()].sort((a,b)=>a.name.localeCompare(b.name))){if(![x.name,x.email,x.phone].join(' ').toLowerCase().includes(search))continue;const visits=rows.filter(b=>b.uid===x.uid&&b.status==='completed').sort((a,b)=>b.date.localeCompare(a.date)),used=balances.get(x.uid)?.used||0,a=document.createElement('article'),title=document.createElement('h3'),info=document.createElement('p'),stats=document.createElement('p');title.textContent=x.name;info.textContent=x.email+' · '+x.phone;stats.textContent=visits.length+' visitas · '+(visits[0]?'Última: '+waDate(visits[0].date):'Sem visitas')+' · '+Math.max(0,visits.length-used)+' créditos disponíveis';a.append(title,info,stats);if(x.id){const b=document.createElement('button');b.textContent='Editar';b.className='secondary';b.onclick=()=>{$('customerId').value=x.id;$('adminCustomerName').value=x.name;$('adminCustomerEmail').value=x.email;$('adminCustomerPhone').value=x.phone;$('customerAdminForm').parentElement.open=true;};a.append(b);}if(x.uid&&campaign?.active&&visits.length-used>=campaign.goal){const b=document.createElement('button');b.textContent='Registrar resgate: '+campaign.name;b.onclick=()=>run(async()=>{if(!confirm('Registrar a entrega da recompensa?'))return;const target=doc(db,'establishments',org,'rewardBalances',x.uid),settings=doc(db,'establishments',org,'loyaltySettings','campaign');await runTransaction(db,async tx=>{const [s,c]=await Promise.all([tx.get(target),tx.get(settings)]),v=s.data()?.used||0,rule=c.data();if(!rule?.active||visits.length-v<rule.goal)throw Error('Saldo insuficiente ou campanha inativa.');tx.set(target,{used:v+rule.goal,lastReward:rule.name,updatedAt:serverTimestamp()});});await renderCustomers();$('status').textContent='Resgate registrado.';});a.append(b);}root.append(a);}if(!root.children.length)root.textContent='Nenhum cliente encontrado.';}
