const statusNames={pending:'Pendente',confirmed:'Confirmado',completed:'Concluído',cancelled:'Cancelado',no_show:'Não compareceu'};
function showBookings(root,snap,cat,staffMode=false){root.replaceChildren();const rows=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));for(const x of rows){const a=document.createElement('article'),h=document.createElement('h3'),t=document.createElement('p');h.textContent=x.date.split('-').reverse().join('/')+' às '+x.time+' · '+(statusNames[x.status]||'Status desconhecido');t.textContent=(staffMode?x.name:cat?.professionals?.find(p=>p.id===x.professional)?.name||'Profissional')+' · '+(cat?.services?.find(s=>s.id===x.service)?.name||'Serviço');a.append(h,t);if(staffMode){const p=staff[Number($('staffProfiles').value)];for(const [label,status] of bookingActions(x)){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(()=>changeBooking(p.org,x.id,status));a.append(b);}}root.append(a);}if(!rows.length)root.textContent='Nenhum agendamento ainda.';if(staffMode){$('staffDaySummary').textContent=waDate(staffDay)+' · '+rows.filter(x=>x.status==='confirmed').length+' confirmado(s) · '+rows.filter(x=>x.status==='pending').length+' pendente(s)';}if(!staffMode){customerNext(rows,cat);lastCustomerRows=rows;renderCustomerHistory(rows,cat);const count=rows.filter(x=>x.status==='completed').length;renderLevels(count);$('loyaltyPoints').textContent=count*100+' XP';$('loyaltyProgress').textContent=count+' atendimentos concluídos · '+Math.max(0,10-count)+' para a meta inicial';renderReward(count,cat);run(async()=>{const uid=auth.currentUser?.uid;if(!uid)return;const s=await getDoc(doc(db,'establishments',bookingOrg,'rewardBalances',uid));if(auth.currentUser?.uid===uid)renderReward(count,cat,s.data()?.used||0);});}}
