async function watchStaff(p){stopStaff?.();waRows=[];waCatalog=null;renderStaffReport();await loadWa(p);const cat=(await getDoc(doc(db,'publicCatalogs',p.org))).data();if(!auth.currentUser||staff[Number($('staffProfiles').value)]!==p)return;stopStaff=onSnapshot(query(collection(db,'establishments',p.org,'bookingRequests'),where('professional','==',p.professional)),snap=>{const rows=snap.docs.map(d=>d.data());waRows=rows;waCatalog=cat;renderStaffReport();pendingPanel($('staffPending'),snap,cat,p);markedCalendar($('staffCalendar'),rows,day=>{staffDay=day;showBookings($('staffBookings'),{docs:snap.docs.filter(d=>d.data().date===day)},cat,true);});showBookings($('staffBookings'),{docs:snap.docs.filter(d=>d.data().date===staffDay)},cat,true);},e=>$('status').textContent=e.message);}

let stopManager=null,staffDay=dateKey(new Date());
function bookingActions(x){return x.status==='pending'?[['Confirmar','confirmed'],['Recusar','cancelled']]:x.status==='confirmed'?[['Concluir','completed'],['Cancelar','cancelled'],['Não compareceu','no_show']]:[];}
const calendarMonths=new WeakMap();
function markedCalendar(root,rows,onDay){let month=calendarMonths.get(root)||new Date();root.replaceChildren();const bar=document.createElement('div');bar.className='cal-head';const title=document.createElement('strong');title.textContent=month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});for(const n of [-1,1]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=n<0?'‹':'›';b.onclick=()=>{calendarMonths.set(root,new Date(month.getFullYear(),month.getMonth()+n,1));markedCalendar(root,rows,onDay)};if(n<0)bar.append(b,title);else bar.append(b)}root.append(bar);const grid=document.createElement('div');grid.className='cal-grid';for(const d of ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']){const e=document.createElement('small');e.textContent=d;grid.append(e)}const y=month.getFullYear(),m=month.getMonth();for(let i=0;i<new Date(y,m,1).getDay();i++)grid.append(document.createElement('span'));for(let i=1;i<=new Date(y,m+1,0).getDate();i++){const key=dateKey(new Date(y,m,i)),b=document.createElement('button'),count=rows.filter(x=>x.date===key&&['pending','confirmed'].includes(x.status)).length;b.type='button';b.className='secondary'+(count?' gold-day':'');b.textContent=i+(count?' ★':'');b.title=count+' agendamento(s) ativo(s)';b.setAttribute('aria-label',key+' — '+b.title);b.onclick=()=>onDay(key);grid.append(b)}root.append(grid);}
