function renderLevels(count){const xp=count*100,levels=[['Bronze',0,'#98603c'],['Silver',300,'#64748b'],['Gold',600,'#946600'],['Platinum',1000,'#367b86'],['Diamond',2000,'#6754b5']];const idx=levels.reduce((a,l,i)=>xp>=l[1]?i:a,0),root=$('levelTrack');root.replaceChildren();for(const [i,l] of levels.entries()){const b=document.createElement('span');b.className='level-badge'+(i===idx?' current-level':'');b.style.setProperty('--level',l[2]);b.textContent=(i<idx?'✓ ':i===idx?'★ ':'')+l[0]+' · '+l[1]+' XP';root.append(b)}const next=levels[idx+1];$('nextLevel').textContent=next?'Próximo nível: '+next[0]+' · faltam '+(next[1]-xp)+' XP':'Nível máximo conquistado!';$('currentLevel').textContent='◆ Nível atual: '+levels[idx][0];$('currentLevel').style.color=levels[idx][2];const bar=$('xpBar');bar.max=next?next[1]-levels[idx][1]:1;bar.value=next?xp-levels[idx][1]:1;}
