const brandFields=[['brandLogo','logo'],['brandAddress','address'],['brandPhone','phone'],['brandReview','review']];
function safeHttps(v){try{const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return ''}}
function readBrand(){const b=Object.fromEntries(brandFields.map(([id,k])=>[k,$(id).value.trim()]));for(const k of ['logo','review'])if(b[k]&&!safeHttps(b[k]))throw Error('Use links HTTPS.');return b;}
function renderBrand(b={}){const root=$('brandPublic');root.replaceChildren();if(safeHttps(b.logo)){const im=new Image();im.src=safeHttps(b.logo);im.alt='Logo do estabelecimento';im.style.cssText='max-width:100px;max-height:100px;object-fit:contain;border-radius:12px';root.append(im)}if(b.address){const p=document.createElement('p');p.textContent=b.address;root.append(p)}const digits=(b.phone||'').replace(/\D/g,'');if(digits.length===10||digits.length===11||digits.length===13){const a=document.createElement('a');a.href='https://wa.me/'+(digits.length===13?digits:'55'+digits);a.textContent='Contato comercial';a.target='_blank';a.rel='noopener noreferrer';root.append(a)}}
function feedbackCard(root,x){const box=document.createElement('div');box.className='booking-feedback';const label=document.createElement('strong');label.textContent='Como foi seu atendimento?';box.append(label);const form=document.createElement('form'),score=document.createElement('select');score.setAttribute('aria-label','Nota do atendimento');for(let n=5;n>=1;n--)score.append(option(String(n),'★'.repeat(n)+' · '+n+'/5'));const comment=document.createElement('textarea');comment.placeholder='Comentário opcional';comment.maxLength=500;const button=document.createElement('button');button.textContent='Enviar avaliação';form.append(score,comment,button);box.append(form);const uid=auth.currentUser?.uid,org=bookingOrg,ref=doc(db,'establishments',org,'feedback',x.id);function done(){form.remove();label.textContent='Obrigado pela sua avaliação!';if(safeHttps(catalog?.brand?.review)){const a=document.createElement('a');a.href=safeHttps(catalog.brand.review);a.target='_blank';a.rel='noopener noreferrer';a.textContent='Avaliar também no Google';box.append(a)}}form.hidden=true;getDoc(ref).then(s=>{if(s.exists())done();else form.hidden=false}).catch(()=>{label.textContent='Avaliação indisponível no momento.'});form.onsubmit=e=>{e.preventDefault();button.disabled=true;run(async()=>{try{await setDoc(ref,{uid,score:Number(score.value),comment:comment.value.trim(),createdAt:serverTimestamp()});done()}finally{button.disabled=false}})};root.append(box)}
$('feedbackRefresh').onclick=()=>run(async()=>{if(!current)return;const org=current.id,s=await getDocs(collection(db,'establishments',org,'feedback'));if(current?.id!==org)return;const root=$('feedbackManager');root.replaceChildren();const rows=s.docs.map(d=>d.data());const title=document.createElement('p');title.textContent=rows.length?`Nota média: ${(rows.reduce((a,b)=>a+b.score,0)/rows.length).toFixed(1)} / 5 · ${rows.length} avaliações`:'Nenhuma avaliação ainda.';root.append(title);for(const x of rows){const a=document.createElement('article');a.textContent='★'.repeat(x.score)+' · '+(x.comment||'Sem comentário');root.append(a)}});

// Maintenance: only the owner, scoped to the selected unit.
async function resetPlan18(org,mode){
 const kinds=['bookingRequests','bookingLocks','rewardBalances','feedback'];
 const snaps=await Promise.all(kinds.map(k=>getDocsFromServer(collection(db,'establishments',org,k))));
 const [book,locks,balances,feedback]=snaps.map(s=>s.docs);
 const targets=mode==='all'?book:book.filter(d=>['pending','confirmed'].includes(d.data().status));
 const ids=new Set(targets.map(d=>d.id));
 const changes=locks.flatMap(d=>{if(mode==='all')return [{ref:d.ref,remove:true,original:d.data()}];const slots=d.data().slots||[],keep=slots.filter(z=>!ids.has(z.id));return keep.length===slots.length?[]:[{ref:d.ref,remove:!keep.length,slots:keep,original:d.data()}];});
 const deletes=[...targets,...(mode==='all'?balances:[]),...feedback.filter(d=>mode==='all'||ids.has(d.id))];
 return {deletes,changes,targets,balances:mode==='all'?balances.length:0};
}
function canonical20(v){if(v===null||typeof v!=='object')return v;if(typeof v.toMillis==='function')return {seconds:v.seconds,nanoseconds:v.nanoseconds};if(Array.isArray(v))return v.map(canonical20);return Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical20(v[k])]));}
function same20(a,b){return JSON.stringify(canonical20(a))===JSON.stringify(canonical20(b));}
let resetBusy18=false;
function resetContext18(){if(!current||current.ownerUid!==auth.currentUser?.uid)throw Error('Selecione uma unidade da qual você é gerente.');return {org:current.id,name:current.name,mode:$('resetDataMode').value};}
$('resetDataMode').onchange=()=>{$('resetDataResult').textContent='';$('resetDataConfirm').value='';};
$('resetDataPreview').onclick=()=>run(async()=>{const c=resetContext18(),p=await resetPlan18(c.org,c.mode);if(current?.id!==c.org)return;$('resetDataResult').textContent=`${c.name}: ${p.targets.length} agendamentos, ${p.changes.length} registros de bloqueio e ${p.balances} saldos de fidelidade afetados.`;});
$('resetDataForm').onsubmit=e=>{e.preventDefault();if(resetBusy18)return;run(async()=>{const c=resetContext18();if($('resetDataConfirm').value.trim()!=='ZERAR')throw Error('Digite ZERAR.');resetBusy18=true;$('resetDataSubmit').disabled=true;try{const p=await resetPlan18(c.org,c.mode);if(current?.id!==c.org)throw Error('Unidade alterada.');if(p.deletes.length+p.changes.length>450)throw Error('Mais de 450 registros. Necessária manutenção administrativa em lotes. Nenhum dado excluído.');if(!confirm(`Excluir definitivamente ${p.targets.length} agendamentos de ${c.name}? Execute somente sem outros usuários operando a agenda.`))return;await runTransaction(db,async tx=>{const refs=[...p.deletes.map(d=>d.ref),...p.changes.map(d=>d.ref)];const fresh=await Promise.all(refs.map(r=>tx.get(r)));for(let i=0;i<p.deletes.length;i++){const old=p.deletes[i],now=fresh[i];if(!now.exists()||!same20(now.data(),old.data()))throw Error('Dados alterados durante a manutenção. Confira novamente.');}for(let i=0;i<p.changes.length;i++){const change=p.changes[i],now=fresh[p.deletes.length+i];if(!now.exists()||!same20(now.data(),change.original))throw Error('Bloqueios alterados. Confira novamente.');if(c.mode==='all'){tx.delete(change.ref);}else{const ids=new Set(p.targets.map(d=>d.id)),keep=(now.data().slots||[]).filter(z=>!ids.has(z.id));if(keep.length)tx.update(change.ref,{slots:keep});else tx.delete(change.ref);}}for(const d of p.deletes)tx.delete(d.ref);});$('resetDataConfirm').value='';$('resetDataResult').textContent='Manutenção concluída. Cadastros e escalas preservados.';if(current?.id===c.org){$('feedbackManager').replaceChildren();await renderCustomers();await renderAgenda();}}finally{resetBusy18=false;$('resetDataSubmit').disabled=false;}});};

async function openSuper(u){const admin=await getDoc(doc(db,'platformAdmins',u.uid));if(auth.currentUser?.uid!==u.uid)return true;if(!admin.exists())return false;$('panel').hidden=true;$('superPanel').hidden=false;await loadSuper();return true;}
$('superLogout').onclick=()=>signOut(auth);
$('superRefresh').onclick=()=>run(loadSuper);
let superRows=[];
async function loadSuper(){const [orgs,subs]=await Promise.all([getDocs(collection(db,'establishments')),getDocs(collection(db,'platformSubscriptions'))]);const map=new Map(subs.docs.map(d=>[d.id,d.data()]));superRows=orgs.docs.map(d=>({id:d.id,...d.data(),sub:map.get(d.id)||{}}));renderSuper();}
$('superSearch').oninput=renderSuper;
function renderSuper(){const root=$('superList');root.replaceChildren();const today=dateKey(new Date());const active=superRows.filter(x=>x.sub.status==='active'&&x.sub.until>=today);$('superMetrics').textContent=`${superRows.length} unidades · ${active.length} assinaturas vigentes · ${money16(active.reduce((n,x)=>n+(x.sub.monthlyCents||0),0))}/mês contratados`;const q=$('superSearch').value.toLowerCase();for(const x of superRows.filter(x=>x.name.toLowerCase().includes(q))){const a=document.createElement('article'),h=document.createElement('h3');h.textContent=x.name;const info=document.createElement('p');info.textContent=x.segment+' · '+x.id;const f=document.createElement('form'),status=document.createElement('select'),until=document.createElement('input'),price=document.createElement('input'),b=document.createElement('button');for(const [v,l] of [['trial','Teste'],['active','Ativa'],['blocked','Bloqueada'],['inactive','Inativa']])status.append(option(v,l));status.value=x.sub.status||'inactive';until.type='date';until.required=true;until.value=x.sub.until||today;price.type='number';price.min='0';price.max='100000';price.step='0.01';price.required=true;price.value=(x.sub.monthlyCents??2990)/100;for(const [label,input] of [['Situação comercial',status],['Válida até',until],['Mensalidade (R$)',price]]){const l=document.createElement('label');l.textContent=label;l.append(input);f.append(l);}b.textContent='Salvar assinatura';f.append(b);f.onsubmit=e=>{e.preventDefault();b.disabled=true;run(async()=>{try{await setDoc(doc(db,'platformSubscriptions',x.id),{status:status.value,until:until.value,monthlyCents:Math.round(Number(price.value)*100),updatedAt:serverTimestamp()});await loadSuper();$('status').textContent='Assinatura salva.'}finally{b.disabled=false}})};a.append(h,info,f);root.append(a);}}
